function fire(){if(!gameOn||paused||over)return;if(player.reload>0||player.shot>0)return;if(player.ammo<=0){reload();return}player.ammo--;player.shot=.22;const a=player.angle+rand(-.035,.035);bullets.push({x:player.x+Math.cos(a)*22,y:player.y+Math.sin(a)*22,vx:Math.cos(a)*760,vy:Math.sin(a)*760,life:.85});particles.push({x:player.x+Math.cos(a)*23,y:player.y+Math.sin(a)*23,vx:Math.cos(a)*65,vy:Math.sin(a)*65,life:.09,max:.09,color:'#ffe29a',size:5});}
function spawnZombie(){const a=rand(0,Math.PI*2),radius=Math.max(viewW,viewH)*.67+80;let x=clamp(player.x+Math.cos(a)*radius,25,WORLD.w-25),y=clamp(player.y+Math.sin(a)*radius,25,WORLD.h-25);for(let n=0;n<12&&blocked(x,y,16);n++){x=rand(40,WORLD.w-40);y=rand(40,WORLD.h-40)}if(blocked(x,y,16)){x=player.x+rand(-350,350);y=player.y+rand(-280,280)}zombies.push({x,y,r:rand(13,17),hp:1+(wave>3&&Math.random()<.25?1:0),speed:rand(39,53)+Math.min(wave*2,25),hit:0,walk:rand(0,7),tone:Math.random()<.5?'#91a36c':'#a2ad79'});}
function burst(x,y,color,count=7){for(let i=0;i<count;i++){const a=rand(0,Math.PI*2),s=rand(30,150),life=rand(.18,.5);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life,max:life,color,size:rand(2,5)})}}
function update(dt){elapsed+=dt;wave=Math.floor(elapsed/22)+1;spawnClock-=dt;const interval=Math.max(.42,1.42-wave*.075);if(spawnClock<=0){spawnZombie();if(wave>2&&Math.random()<.22)spawnZombie();spawnClock=interval}
const mx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+(touch.active?touch.dx:0),my=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+(touch.active?touch.dy:0),len=Math.hypot(mx,my)||1;moveEntity(player,mx/len*player.speed*dt,my/len*player.speed*dt,player.r);
if(mouse.down||touch.shoot)fire();if(player.shot>0)player.shot-=dt;if(player.invuln>0)player.invuln-=dt;if(player.reload>0){player.reload-=dt;if(player.reload<=0){player.ammo=player.mag;ui.status.textContent='SOBREVIVÊNCIA EM ANDAMENTO'}}
for(let i=bullets.length-1;i>=0;i--){const b=bullets[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(b.life<=0||blocked(b.x,b.y,3)){bullets.splice(i,1);continue}let hit=false;for(let j=zombies.length-1;j>=0;j--){const z=zombies[j];if(Math.hypot(z.x-b.x,z.y-b.y)<z.r+3){z.hp--;burst(b.x,b.y,'#d7e58e',3);bullets.splice(i,1);hit=true;if(z.hp<=0){burst(z.x,z.y,'#769257',9);if(Math.random()<.13)drops.push({x:z.x,y:z.y,type:Math.random()<.6?'ammo':'med',spin:0});zombies.splice(j,1);kills++}break}}if(hit)continue}
for(const z of zombies){const dx=player.x-z.x,dy=player.y-z.y,d=Math.hypot(dx,dy)||1;z.walk+=dt*7;let vx=dx/d,vy=dy/d;const nx=z.x+vx*z.speed*dt,ny=z.y+vy*z.speed*dt;if(blocked(nx,z.y,z.r)){vx=0;vy=Math.sign(dy)||1}if(blocked(z.x,ny,z.r)){vy=0;vx=Math.sign(dx)||1}moveEntity(z,vx*z.speed*dt,vy*z.speed*dt,z.r);if(d<z.r+player.r+3&&player.invuln<=0){player.hp-=12;player.invuln=.65;screenShake=8;burst(player.x,player.y,'#ef6c59',8);if(player.hp<=0){player.hp=0;finish()}}}
for(let i=drops.length-1;i>=0;i--){const d=drops[i];d.spin+=dt;if(Math.hypot(player.x-d.x,player.y-d.y)<player.r+17){if(d.type==='med')player.hp=Math.min(100,player.hp+28);else player.ammo=Math.min(player.mag,player.ammo+6);burst(d.x,d.y,d.type==='med'?'#9cdf76':'#efc36c',8);drops.splice(i,1)}}
for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.91;p.vy*=.91;p.life-=dt;if(p.life<=0)particles.splice(i,1)}screenShake=Math.max(0,screenShake-dt*20);updateHud();}
function finish(){if(over)return;over=true;gameOn=false;ui.status.textContent='SINAL PERDIDO';document.getElementById('endKicker').textContent=`${kills} INFECTADOS ELIMINADOS`;document.getElementById('endTitle').innerHTML='Você <em>caiu.</em>';document.getElementById('endCopy').textContent=`Você resistiu por ${formatTime(elapsed)} e alcançou a onda ${wave}. A cidade ainda precisa de você.`;ui.end.classList.remove('hidden')}
function formatTime(s){const m=Math.floor(s/60),sec=Math.floor(s%60);return`${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`}
function updateHud(){ui.wave.textContent=String(wave).padStart(2,'0');ui.kills.textContent=kills;ui.time.textContent=formatTime(elapsed);ui.healthText.textContent=`${Math.ceil(player.hp)}%`;ui.healthBar.style.width=`${player.hp}%`;ui.healthBar.style.background=player.hp<35?'linear-gradient(90deg,#c5443b,#f16e5b)':'linear-gradient(90deg,#9ac84f,#d8f36a)';ui.ammoText.textContent=player.reload>0?'RECARREGANDO':`${player.ammo} / ${player.mag}`;ui.ammoBar.style.width=`${player.reload>0?Math.max(0,(1.1-player.reload)/1.1*100):player.ammo/player.mag*100}%`}

