function loop(ts){
  if(!gameOn||paused||over){
    drawWorld();
    if(!gameOn && !over && !ui.start.classList.contains('hidden')) drawWorld();
    if(!gameOn && !over) return;
    requestAnimationFrame(loop);
    return;
  }
  const dt=Math.min((ts-last)/1000,0.033); last=ts;
  update(dt);
  drawWorld();
  requestAnimationFrame(loop);
}

buildWorld();
updateHud();
drawWorld();
window.addEventListener('blur',()=>{if(gameOn&&!over)togglePause()});
})();
</script>
</body>
